import csv, ast, datetime, calendar
from collections import defaultdict

with open('/app/dataset/employees.csv') as f:
    emps = list(csv.DictReader(f))
emp_by_pesel = {e['PESEL']: e for e in emps}
valid_pesels = list(emp_by_pesel.keys())

with open('/app/dataset/tasks.csv') as f:
    tasks = list(csv.DictReader(f))
task_by_id = {t['task_id']: t for t in tasks}

with open('/app/dataset/timesheet.csv') as f:
    ts = list(csv.DictReader(f))

def hamming(a,b):
    return sum(1 for x,y in zip(a,b) if x!=y)

def correct_employee_id(eid):
    if eid in emp_by_pesel:
        return eid
    if len(eid) != 11 or not eid.isdigit():
        return None
    dists = sorted((hamming(eid,v), v) for v in valid_pesels)
    if dists[0][0] <= 3 and (len(dists)==1 or dists[1][0] - dists[0][0] >= 3):
        return dists[0][1]
    return None

def correct_date(s):
    try:
        return datetime.date.fromisoformat(s)
    except ValueError:
        y,m,d = s.split('-')
        y,m,d = int(y),int(m),int(d)
        maxday = calendar.monthrange(y,m)[1]
        d = min(d, maxday)
        return datetime.date(y,m,d)

rows = []
seen = set()
excluded = []
for t in ts:
    eid = correct_employee_id(t['employee_id'])
    if eid is None:
        excluded.append(t)
        continue
    date = correct_date(t['date'])
    try:
        hours = float(t['hours_worked'])
    except:
        excluded.append(t)
        continue
    try:
        tlist = ast.literal_eval(t['performed_tasks'])
    except:
        tlist = []
    tlist = [str(x) for x in tlist]
    key = (eid, date.isoformat(), hours, tuple(sorted(tlist)), t['facility_id'])
    if key in seen:
        continue
    seen.add(key)
    bonus = sum(float(task_by_id[x]['pay_per_completion']) for x in tlist if x in task_by_id)
    rows.append({'eid':eid, 'date':date, 'hours':hours, 'bonus':bonus})

print('total rows kept', len(rows), 'excluded', len(excluded))
print('excluded sample', excluded[:5])

min_date = min(r['date'] for r in rows)
max_date = max(r['date'] for r in rows)
print('min/max date', min_date, max_date, min_date.strftime('%A'))
"

